289	              StandardWatchEventKinds.ENTRY_DELETE
290	            );
291	            server = ManagementFactory.getPlatformMBeanServer();
292	            final ObjectName loaderName = new ObjectName(Q2_CLASS_LOADER);
293	            try {
294	                loader = new QClassLoader(server, libDir, loaderName, mainClassLoader);
295	                if (server.isRegistered(loaderName))
296	                    server.unregisterMBean(loaderName);
297	                server.registerMBean(loader, loaderName);
298	                loader = loader.scan(false);
299	            } catch (Throwable t) {
300	                if (log != null)
301	                    log.error("initial-scan", t);
302	                else
303	                    t.printStackTrace();
304	            }
305	            factory = new QFactory(loaderName, this);
306	            writePidFile();
307	            initSystemLogger();
308	            if (!noShutdownHook)
309	                addShutdownHook();
310	            q2Thread = Thread.currentThread();
311	            q2Thread.setContextClassLoader(loader);
312	            if (cli != null)
313	                cli.start();
314	            initConfigDecorator();
315	            if (metricsPort != 0) {
316	                deployElement(
317	                  PrometheusService.createDescriptor(metricsPort, metricsPath, statusPath),
318	                  "00_prometheus-" + getInstanceId() + ".xml", false, true);
319	            }
320	
321	            deployInternal();
322	            for (int i = 1; shutdown.getCount() > 0; i++) {
323	                try {
324	                    if (i > 1 && disableDeployScan) {
325	                        shutdown.await();
326	                        break;
327	                    }
328	                    boolean forceNewClassLoader = scan() && i > 1;
329	                    QClassLoader oldClassLoader = loader;
330	                    loader = loader.scan(forceNewClassLoader);
331	                    if (loader != oldClassLoader) {
332	                        oldClassLoader = null; // We want this to be null so it gets GCed.
333	                        System.gc();  // force a GC
334	                        log.info(
335	                          "new classloader ["
336	                            + Integer.toString(loader.hashCode(), 16)
337	                            + "] has been created"
338	                        );
339	                        q2Thread.setContextClassLoader(loader);
340	                    }
341	                    logVersion();
342	
343	                    deploy();
344	                    checkModified();
345	                    ready.countDown();
346	                    if (!waitForChanges(service))
347	                        break;
348	                } catch (InterruptedException | IllegalAccessError ignored) {
349	                    // NOPMD
350	                } catch (Throwable t) {
351	                    log.error("start", t.getMessage());
352	                    relax();
353	                }
354	            }
355	            undeploy();
356	            try {
357	                if (server.isRegistered(loaderName))
358	                    server.unregisterMBean(loaderName);
359	            } catch (InstanceNotFoundException e) {
360	                log.error(e);
361	            }
362	            if (decorator != null) {
363	                decorator.uninitialize();
364	            }
365	            if (exit && !shuttingDown)
366	                System.exit(0);
367	        } catch (IllegalAccessError ignored) {
368	            // NOPMD OK to happen
369	        } catch (Exception e) {
370	            if (log != null)
371	                log.error (e);
372	            else
373	                e.printStackTrace();
374	            System.exit (1);
375	        } finally {
376	            stopJFR();
377	        }
