465	    private void deploy () {
466	        List<ObjectInstance> startList = new ArrayList<ObjectInstance>();
467	        Iterator<Map.Entry<File,QEntry>> iter = dirMap.entrySet().iterator();
468	
469	        try {
470	            while (iter.hasNext() && shutdown.getCount() > 0) {
471	                Map.Entry<File,QEntry> entry = iter.next();
472	                File   f        = entry.getKey ();
473	                QEntry qentry   = entry.getValue ();
474	                long deployed   = qentry.getDeployed ();
475	                if (deployed == 0) {
476	                    if (deploy(f)) {
477	                        if (qentry.isQBean ()) {
478	                            if (qentry.isEagerStart())
479	                                start(qentry.getInstance());
480	                            else
481	                                startList.add(qentry.getInstance());
482	                        }
483	                        qentry.setDeployed (f.lastModified ());
484	                    } else {
485	                        // deploy failed, clean up.
486	                        iter.remove();
487	                    }
488	                } else if (deployed != f.lastModified ()) {
489	                    undeploy (f);
490	                    iter.remove ();
491	                    loader.forceNewClassLoaderOnNextScan();
492	                }
493	            }
494	            for (ObjectInstance instance : startList)
495	                start(instance);
496	        }
497	        catch (Exception e){
498	            log.error ("deploy", e);
499	        }
500	    }
