502	    private void undeploy () {
503	        Object[] set = dirMap.entrySet().toArray ();
504	        int l = set.length;
505	
506	        while (l-- > 0) {
507	            Map.Entry entry = (Map.Entry) set[l];
508	            File   f  = (File) entry.getKey ();
509	            undeploy (f);
510	        }
511	    }
