515	            new Thread ("Q2-ShutdownHook") {
516	                public void run () {
517	                    audit (new Shutdown(getInstanceId(), shutdownHookDelay));
518	                    if (shutdownHookDelay > 0)
519	                        ISOUtil.sleep(shutdownHookDelay);
520	
521	                    audit(auditStop(Duration.between(startTime, Instant.now())));
522	                    shuttingDown = true;
523	                    shutdown.countDown();
524	                    if (q2Thread != null) {
525	                        try {
526	                            q2Thread.join (SHUTDOWN_TIMEOUT);
527	                        } catch (InterruptedException ignored) {
528	                            // NOPMD nothing to do
529	                        } catch (NullPointerException ignored) {
530	                            // NOPMD
531	                            // on thin Q2 systems where shutdown is very fast,
532	                            // q2Thread can become null between the upper if and
533	                            // the actual join. Not a big deal so we ignore the
534	                            // exception.
535	                        }
536	                    }
537	                }
538	            }
539	        );
540	    }
