579	    private long persist (File f, ObjectName name) {
580	        long deployed = f.lastModified ();
581	        try {
582	            Element e = (Element) server.getAttribute (name, "Persist");
583	            if (e != null) {
584	                XMLOutputter out = new XMLOutputter (Format.getPrettyFormat());
585	                Document doc = new Document ();
586	                e.detach();
587	                doc.setRootElement (e);
588	                File tmp = new File (f.getAbsolutePath () + ".tmp");
589	                Writer writer = new BufferedWriter(new FileWriter(tmp));
590	                try {
591	                    out.output (doc, writer);
592	                } finally {
593	                    writer.close ();
594	                }
595	                f.delete();
596	                tmp.renameTo (f);
597	                deployed = f.lastModified ();
598	            }
599	        } catch (Exception ex) {
600	            log.warn ("persist", ex);
601	        }
602	        return deployed;
603	    }
