641	    private boolean deploy (File f) {
642	        LogEvent evt = getDeployLog().createInfo().withTraceId(getInstanceId());
643	        boolean enabled;
644	        try {
645	            QEntry qentry = dirMap.get (f);
646	            SAXBuilder builder = createSAXBuilder();
647	            Document doc;
648	            if(decorator!=null && !f.getName().equals(LOGGER_CONFIG))
649	            {
650	                doc=decrypt(builder.build(new StringReader(decorator.decorateFile(f))));
651	            }
652	            else
653	            {
654	                doc=decrypt(builder.build(f));
655	            }
656	
657	            Element rootElement = doc.getRootElement();
658	            String iuuid = rootElement.getAttributeValue ("instance");
659	            if (iuuid != null) {
660	                UUID uuid = UUID.fromString(iuuid);
661	                if (!uuid.equals (getInstanceId())) {
662	                    deleteFile (f, iuuid);
663	                    return false;
664	                }
665	            }
666	            enabled = QFactory.isEnabled(rootElement);
667	            qentry.setEagerStart(QFactory.isEagerStart(rootElement));
668	            if (evt != null)
669	                evt.addMessage(new Deploy(f.getCanonicalPath(), enabled, qentry.isEagerStart()));
670	            if (enabled) {
671	                Object obj = factory.instantiate (this, factory.expandEnvProperties(rootElement));
672	                qentry.setObject (obj);
673	                ObjectInstance instance = factory.createQBean (
674	                    this, doc.getRootElement(), obj
675	                );
676	                qentry.setInstance (instance);
677	            }
678	        }
679	        catch (InstanceAlreadyExistsException e) {
680	           /*
681	            * Ok, the file we tried to deploy, holds an object
682	            *  that already has been deployed.
683	            *
684	            * Rename it out of the way.
685	            *
686	            */
687	            tidyFileAway(f,DUPLICATE_EXTENSION, evt);
688	            if (evt != null)
689	                evt.addMessage(e);
690	            return false;
691	        }
692	        catch (Exception e) {
693	            if (evt != null) {
694	                evt.addMessage(e);
695	            }
696	            tidyFileAway(f,ERROR_EXTENSION, evt);
697	            // This will also save deploy error repeats...
698	            return false;
699	        }
700	        catch (Error e) {
701	            if (evt != null)
702	                evt.addMessage(e);
703	            tidyFileAway(f,ENV_EXTENSION, evt);
704	            // This will also save deploy error repeats...
705	            return false;
706	        } finally {
707	            if (evt != null) {
708	                Logger.log(evt);
709	            }
710	        }
711	        return true ;
712	    }
