 38	public class SimpleConfigurationFactory implements ConfigurationFactory {
 39	    @Override
 40	    public Configuration getConfiguration(Element e) throws ConfigurationException {
 41	        Properties props = new Properties();
 42	        for (Element property : e.getChildren("property")) {
 43	            String name = property.getAttributeValue("name");
 44	            String value = property.getAttributeValue("value");
 45	            String baseFile = property.getAttributeValue("file");
 46	            if (baseFile != null) {
 47	            	boolean isEnv = Boolean.parseBoolean(property.getAttributeValue("env", "false"));
 48	                processFile(props, baseFile, isEnv);
 49	            } else if (name != null && value != null) {
 50	                processProperty(props, name, value);
 51	            }
 52	        }
 53	        return new SimpleConfiguration(props);
 54	    }
 55	
 56	    protected void processProperty(Properties props, String name, String value) {
 57	        Object obj = props.get(name);
 58	        if (obj instanceof String[]) {
 59	            String[] mobj = (String[]) obj;
 60	            String[] m = new String[mobj.length + 1];
 61	            System.arraycopy(mobj, 0, m, 0, mobj.length);
 62	            m[mobj.length] = value;
 63	            props.put(name, m);
 64	        } else if (obj instanceof String) {
 65	            String[] m = new String[2];
 66	            m[0] = (String) obj;
 67	            m[1] = value;
 68	            props.put(name, m);
 69	        } else
 70	            props.put(name, value);
 71	    }
 72	
 73	    protected void processFile(Properties props, String baseFile, boolean isEnv) throws ConfigurationException {
 74	        baseFile = Environment.get(baseFile);
 75	        boolean foundFile = false;
 76	        for (String file : getFiles(baseFile, isEnv?Environment.getEnvironment().getName():"")) {
 77	            foundFile |= readYamlFile(props, file);
 78	        }
 79	        if (!foundFile) {
 80	            throw new ConfigurationException("Could not find any matches for file: " + baseFile);
 81	        }
 82	    }
 83	
 84	    protected List<String> getFiles(String baseFile, String environmnents) {
 85	        List<String> files = new ArrayList<>();
 86	        files.add(baseFile);
 87	        if (baseFile.endsWith(".yml") || baseFile.endsWith(".properties")) {
 88	            baseFile = baseFile.substring(0, baseFile.lastIndexOf("."));
 89	        }
 90	        for (String env : ISOUtil.commaDecode(environmnents)) {
 91	            if (!ISOUtil.isBlank(env)) {
 92	                files.add(baseFile + "-" + env + ".yml");
 93	                files.add(baseFile + "-" + env + ".properties");
 94	            }
 95	        }
 96	        return files;
 97	    }
 98	
 99	    protected boolean readYamlFile(Properties props, String fileName) throws ConfigurationException {
100	        try {
101	            if (fileName.endsWith(".yml")) {
102	                return readYAML(props, fileName);
103	            } else {
104	                return readPropertyFile(props, fileName);
105	            }
106	        } catch (Exception ex) {
107	            throw new ConfigurationException(fileName, ex);
108	        }
109	    }
110	
111	    protected boolean readPropertyFile(Properties props, String fileName) throws IOException {
112	        File f = new File(fileName);
113	        if (f.exists() && f.canRead()) {
114	            try (FileInputStream in = new FileInputStream(f)) {
115	                props.load(in);
116	                return true;
117	            }
118	        }
119	        return false;
120	    }

